/* sw.js — JLPT PWA service worker.  Scope: /  (must be at site root) */
'use strict';

/* Bump BUILD on every deploy. Everything else derives from it. */
const BUILD   = '2026.09.21.1';
const SHELL   = `shell-${BUILD}`;   // app shell, replaced wholesale each build
const DATA    = 'data-v1';          // level JSON: content-hashed URLs, immutable
const MEDIA   = 'media-v1';         // same-origin audio/images, LRU-trimmed
const KEEP    = new Set([SHELL, DATA, MEDIA]);

/* Shell = only what is needed to render ANY screen. Keep it small so install
   never fails: one bad URL rejects a whole addAll(). */
const SHELL_URLS = [
  '/', '/index.html', '/offline.html',
  '/css/app.css',
  '/js/boot.js', '/js/app.js', '/js/router.js', '/js/store.js', '/js/srs.js',
  '/vendor/ts-fsrs.mjs',
  '/manifest.webmanifest',
  '/icons/icon-192.png', '/icons/icon-512.png', '/icons/maskable-512.png',
  '/data/index.json'                 // tiny catalogue: levels -> file list + bytes
];

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL);
    // Add individually so a single 404 cannot brick the whole install.
    await Promise.all(SHELL_URLS.map(async (u) => {
      try { await c.add(new Request(u, { cache: 'reload' })); }
      catch (err) { console.warn('[sw] precache miss', u, err); }
    }));
    // NOTE: deliberately NO skipWaiting() here. The new SW waits; the page shows
    // "Update ready" and posts {type:'SKIP_WAITING'} when the user taps it.
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.map((n) => KEEP.has(n) ? null : caches.delete(n)));
    if (self.registration.navigationPreload) {
      await self.registration.navigationPreload.enable();
    }
    await self.clients.claim();
  })());
});

/* ---------- routing ---------- */

const isData  = (u) => u.pathname.startsWith('/data/');
const isMedia = (u) => u.pathname.startsWith('/audio/') || u.pathname.startsWith('/img/');

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;                 // never intercept writes
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;  // CRITICAL: let cross-origin pass
                                                    // through untouched (YouTube, dict
                                                    // APIs, TTS audio). Caching opaque
                                                    // responses costs ~7MB quota each.

  // 1. Navigations -> app shell (SPA). Network first for freshness, shell on failure.
  if (req.mode === 'navigate') {
    event.respondWith((async () => {
      try {
        const pre = await event.preloadResponse;
        if (pre) return pre;
        return await fetch(req);
      } catch {
        const c = await caches.open(SHELL);
        return (await c.match('/index.html')) ||
               (await c.match('/offline.html')) ||
               new Response('Offline', { status: 503 });
      }
    })());
    return;
  }

  // 2. Level data: content-hashed => immutable => cache-first, never revalidate.
  if (isData(url)) {
    event.respondWith((async () => {
      const c = await caches.open(DATA);
      const hit = await c.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) c.put(req, res.clone());
      return res;
    })());
    return;
  }

  // 3. Same-origin media. Range requests (Safari <audio>) MUST get a 206 or
  //    playback fails silently with no console error.
  if (isMedia(url)) {
    event.respondWith(serveMedia(req));
    return;
  }

  // 4. Everything else (shell assets): cache-first + background refresh.
  event.respondWith((async () => {
    const c = await caches.open(SHELL);
    const hit = await c.match(req);
    const net = fetch(req).then((res) => {
      if (res && res.ok) c.put(req, res.clone());
      return res;
    }).catch(() => null);
    return hit || (await net) || new Response('', { status: 504 });
  })());
});

async function serveMedia(req) {
  const c = await caches.open(MEDIA);
  const range = req.headers.get('range');
  const bare  = new Request(req.url, { headers: {} }); // cache key without Range
  let res = await c.match(bare);
  if (!res) {
    try {
      res = await fetch(bare);
      if (res.ok) await c.put(bare, res.clone());
    } catch {
      return new Response('', { status: 504 });
    }
  }
  if (!range) return res;
  const buf   = await res.arrayBuffer();
  const m     = /bytes=(\d*)-(\d*)/.exec(range) || [];
  const start = m[1] ? parseInt(m[1], 10) : 0;
  const end   = m[2] ? parseInt(m[2], 10) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type':   res.headers.get('Content-Type') || 'audio/mpeg',
      'Content-Range':  `bytes ${start}-${end}/${buf.byteLength}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges':  'bytes'
    }
  });
}

/* ---------- explicit "Download this level for offline" ---------- */

self.addEventListener('message', (e) => {
  const msg = e.data || {};
  if (msg.type === 'SKIP_WAITING')   { self.skipWaiting(); return; }
  if (msg.type === 'DOWNLOAD_LEVEL') e.waitUntil(downloadLevel(msg, e.source));
  if (msg.type === 'REMOVE_LEVEL')   e.waitUntil(removeLevel(msg, e.source));
  if (msg.type === 'USAGE')          e.waitUntil(reportUsage(e.source));
});

async function downloadLevel({ level, urls }, client) {
  const c = await caches.open(DATA);
  let done = 0;
  const CONC = 4;                              // gentle on mobile radios
  const queue = urls.slice();
  const worker = async () => {
    while (queue.length) {
      const u = queue.shift();
      try {
        if (!(await c.match(u))) {
          const r = await fetch(u, { cache: 'no-store' });
          if (r.ok) await c.put(u, r.clone());
          else throw new Error('HTTP ' + r.status);
        }
      } catch (err) {
        client && client.postMessage({ type: 'LEVEL_ERROR', level, url: u, message: String(err) });
      }
      done++;
      client && client.postMessage({ type: 'LEVEL_PROGRESS', level, done, total: urls.length });
    }
  };
  await Promise.all(Array.from({ length: Math.min(CONC, urls.length) }, worker));
  client && client.postMessage({ type: 'LEVEL_READY', level });
}

async function removeLevel({ level, urls }, client) {
  const c = await caches.open(DATA);
  await Promise.all(urls.map((u) => c.delete(u)));
  client && client.postMessage({ type: 'LEVEL_REMOVED', level });
}

async function reportUsage(client) {
  let est = {};
  try { est = await navigator.storage.estimate(); } catch {}
  client && client.postMessage({ type: 'USAGE', usage: est.usage || 0, quota: est.quota || 0 });
}


