// Register + non-destructive update flow -------------------------------------
let reg;
if ('serviceWorker' in navigator) {
  window.addEventListener('load', async () => {
    reg = await navigator.serviceWorker.register('/sw.js', { scope: '/', updateViaCache: 'none' });

    const showUpdate = (worker) => {
      const bar = document.getElementById('updateBar');
      bar.hidden = false;
      document.getElementById('updateBtn').onclick = () => {
        worker.postMessage({ type: 'SKIP_WAITING' });
      };
    };
    if (reg.waiting && navigator.serviceWorker.controller) showUpdate(reg.waiting);
    reg.addEventListener('updatefound', () => {
      const w = reg.installing;
      w && w.addEventListener('statechange', () => {
        // controller present => this is an UPGRADE, not a first install
        if (w.state === 'installed' && navigator.serviceWorker.controller) showUpdate(w);
      });
    });

    let reloading = false;                       // guard against reload loops
    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (reloading) return; reloading = true; location.reload();
    });

    // Check for a new build when the app comes back to the foreground.
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') reg.update().catch(() => {});
    });
  });
}

// Persistent storage: ask EVERY launch, not once ------------------------------
// On iOS WebKit grants this mainly via the "is a Home Screen app" heuristic,
// so the answer can change between launches.
export async function ensurePersisted() {
  if (!navigator.storage?.persist) return false;
  try {
    if (await navigator.storage.persisted()) return true;
    return await navigator.storage.persist();
  } catch { return false; }
}
ensurePersisted().then((ok) => {
  if (!ok && isIOS() && !isStandalone()) document.getElementById('iosInstall')?.showModal();
});

// Install -------------------------------------------------------------------
const isStandalone = () =>
  matchMedia('(display-mode: standalone)').matches ||
  matchMedia('(display-mode: fullscreen)').matches ||
  navigator.standalone === true;
const isIOS = () =>
  /iphone|ipad|ipod/i.test(navigator.userAgent) ||
  (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);

let deferredPrompt = null;
const installBtn = document.getElementById('installBtn');

window.addEventListener('beforeinstallprompt', (e) => {   // Chromium only
  e.preventDefault();
  deferredPrompt = e;
  if (!isStandalone()) installBtn.hidden = false;
});
installBtn?.addEventListener('click', async () => {
  if (deferredPrompt) {
    deferredPrompt.prompt();
    await deferredPrompt.userChoice;
    deferredPrompt = null;
    installBtn.hidden = true;
  } else if (isIOS()) {
    document.getElementById('iosInstall').showModal();   // Safari has no prompt API
  }
});
window.addEventListener('appinstalled', () => { installBtn.hidden = true; deferredPrompt = null; });
if (isIOS() && !isStandalone()) installBtn.hidden = false;  // iOS never fires the event

// Wake lock (video / timed review). Must be re-acquired after backgrounding. --
let wakeLock = null;
export async function keepAwake(on) {
  try {
    if (on) { wakeLock = wakeLock || await navigator.wakeLock?.request('screen'); }
    else    { await wakeLock?.release(); wakeLock = null; }
  } catch { wakeLock = null; }          // iOS < 18.4 in a PWA, low battery, etc.
}
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible' && wakeLock === null && window.__wantAwake) keepAwake(true);
});

// Haptics: Android only. Never make feedback depend on this. -----------------
export const buzz = (p) => { try { navigator.vibrate?.(p); } catch {} };

// Backup / restore — the only thing that truly cannot be evicted -------------
export async function exportBackup(db) {
  const payload = {
    schemaVersion: 1,
    exportedAt: new Date().toISOString(),
    app: 'nihongo-ladder',
    savedWords: await db.getAll('savedWords'),
    srsState:   await db.getAll('srs'),
    reviewLog:  await db.getAll('reviews'),
    settings:   await db.getAll('settings')
  };
  const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
  const a = Object.assign(document.createElement('a'), {
    href: URL.createObjectURL(blob),
    download: `nihongo-backup-${new Date().toISOString().slice(0, 10)}.json`
  });
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

// Offline download control ---------------------------------------------------
export function downloadLevel(level, urls, onProgress) {
  return new Promise((resolve) => {
    const ch = (e) => {
      const d = e.data;
      if (d.level !== level) return;
      if (d.type === 'LEVEL_PROGRESS') onProgress(d.done / d.total);
      if (d.type === 'LEVEL_READY') { navigator.serviceWorker.removeEventListener('message', ch); resolve(); }
    };
    navigator.serviceWorker.addEventListener('message', ch);
    navigator.serviceWorker.controller?.postMessage({ type: 'DOWNLOAD_LEVEL', level, urls });
  });
}


