// RUNTIME: must be called synchronously inside the tap handler on iOS.
let voicesReady = null;
function jaVoice() {
  voicesReady = voicesReady || new Promise((res) => {
    const pick = () => speechSynthesis.getVoices().find(v => v.lang?.startsWith('ja'));
    const v = pick();                                  // Safari is synchronous
    if (v) return res(v);
    speechSynthesis.addEventListener('voiceschanged', () => res(pick()), { once: true });
    setTimeout(() => res(pick()), 1000);               // Chrome is async; don't hang
  });
  return voicesReady;
}

export async function say(entry) {           // { audio?: '/audio/abc.mp3', word, reading }
  if (entry.audio) {
    const a = new Audio(entry.audio);        // <audio> needs no CORS; SW serves 206 ranges
    try { await a.play(); return true; } catch {}
  }
  if (!('speechSynthesis' in window)) return false;
  const v = await jaVoice();
  if (!v) return false;                      // hide the speaker button instead of faking it
  const u = new SpeechSynthesisUtterance(entry.reading || entry.word);
  u.voice = v; u.lang = 'ja-JP'; u.rate = 0.85;
  speechSynthesis.cancel();                  // Chrome queues indefinitely otherwise
  speechSynthesis.speak(u);
  return true;
}


